// Version A: utility function
function calcDiscount(price: number, loyalty: number) {
  if (loyalty > 100) return price * 0.1
  return 0
}

class RetailCustomer {
  getPrice() { return 100 }
  discount() { return calcDiscount(this.getPrice(), this.loyalty) }
}

class CorporateCustomer {
  getPrice() { return 80 }
  discount() { return calcDiscount(this.getPrice(), this.loyalty) }
}

// Version B: superclass method
class Customer {
  discount() { if (this.loyalty > 100) return this.getPrice() * 0.1; return 0 }
}

class RetailCustomer extends Customer { getPrice() { return 100 } }
class CorporateCustomer extends Customer { getPrice() { return 80 } }
